#!/usr/bin/env pwsh
# Generated by Claude Opus 4.8 (claude.ai/code) · 2026-11-11

<#
.SYNOPSIS
  Backup sequencer — plan, run, and review service backups.
.DESCRIPTION
  Orchestrates per-service backups within a time window, mandatory services
  first, recording events and reporting the result. Services are described in a
  JSON config and implemented by step scripts (recipes or bespoke). See docs/ for
  internals and help/ for usage.
.PARAMETER Command
  plan | validate | run | status | show | history | trash | test-notify | help
.PARAMETER RunRef
  show: which run(s) - 'latest' (default), run ids, or any unique ending of one.
  trash: which trash item(s), by name (default: all).
.PARAMETER ConfigPath
  Path to config.json. Defaults to the OS config dir (see help/).
.PARAMETER ForceWindow
  Run even when outside the configured time window (manual/test runs).
.PARAMETER ForceAllJobs
  Skip the fit check: attempt every planned job, no deferral (accepts overruns).
.PARAMETER Limit
  history: number of recent runs to show.
.PARAMETER Delete
  trash: delete the items now (all, or the names given) instead of listing them.
.EXAMPLE
  pwsh sequencer.ps1 plan
.EXAMPLE
  pwsh sequencer.ps1 run -ConfigPath ./config.json -ForceWindow -ForceAllJobs
.EXAMPLE
  pwsh sequencer.ps1 show 332d
.EXAMPLE
  pwsh sequencer.ps1 trash -Delete host-config-5468a97d02ac
#>

[CmdletBinding()]
param(
    [Parameter(Position = 0)][string]$Command = 'help',
    [Parameter(Position = 1, ValueFromRemainingArguments = $true)][string[]]$RunRef,
    [string]$ConfigPath,
    [switch]$ForceWindow,
    [switch]$ForceAllJobs,
    [int]$Limit = 20,
    [switch]$Delete,
    [switch]$Help
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$BaseDir = $PSScriptRoot
Import-Module (Join-Path $BaseDir 'lib/BackupCommon.psm1') -Force

function Get-ConfigDir {
    if ($env:BACKUP_SEQUENCER_CONFIG_DIR) { return $env:BACKUP_SEQUENCER_CONFIG_DIR }
    if ($IsWindows) { return (Join-Path $env:ProgramData 'backup-sequencer') }
    return '/etc/backup-sequencer'
}

function Get-VarDir {
    if ($env:BACKUP_SEQUENCER_VAR_DIR) { return $env:BACKUP_SEQUENCER_VAR_DIR }
    if ($IsWindows) { return (Join-Path (Join-Path $env:ProgramData 'backup-sequencer') 'var') }
    return '/var/lib/backup-sequencer'
}

function Get-SpoolDefault {
    # transient backups awaiting archive -> /var/spool (FHS: data awaiting processing)
    if ($env:BACKUP_SEQUENCER_SPOOL_DIR) { return $env:BACKUP_SEQUENCER_SPOOL_DIR }
    if ($IsWindows) { return (Join-Path (Join-Path $env:ProgramData 'backup-sequencer') 'spool') }
    return '/var/spool/backup-sequencer'
}

function Format-DisplayTime {
    # ConvertFrom-Json parses the ISO ts into [datetime]; render it back as ISO
    # 8601 explicitly so output doesn't follow the pwsh culture (e.g. US 12h).
    param($Ts)
    if ($null -eq $Ts -or "$Ts" -eq '') { return 'never' }
    try { return ([datetime]$Ts).ToLocalTime().ToString('yyyy-MM-ddTHH:mm:sszzz', [System.Globalization.CultureInfo]::InvariantCulture) }
    catch { return [string]$Ts }
}

function Show-Usage {
    @'
backup sequencer

Usage:
  pwsh sequencer.ps1 <command> [<run>...] [-ConfigPath <path>] [-ForceWindow] [-ForceAllJobs] [-Limit <n>] [-Delete]

Commands:
  plan      Show the ordered plan for the current window (no side effects)
  validate  Check each service's config and prerequisites; run nothing (exit 1 if any invalid)
  run       Execute the plan
  status    The run in progress (step, elapsed), or the last run if idle
  show      Detail of runs: show [latest | <run id> | <unique end of id>]...
  history   Show recent run summaries (newest first, incl. running/interrupted)
  trash     What the spool's trash/ holds and where it came from; -Delete [<name>...]
            deletes it now (all, or the names given; refused during a run)
  test-notify  Mail the last run's report now, marked [test], to check the notify
            settings (sent even when notify is disabled)
  help      This message

Config resolution (unless -ConfigPath is given):
  Linux:    /etc/backup-sequencer/config.json
  Windows:  %ProgramData%\backup-sequencer\config.json
'@ | Write-Host
}

if ($Help -or $Command -eq 'help') {
    Show-Usage
    return
}

if (-not $ConfigPath) {
    $ConfigPath = Join-Path (Get-ConfigDir) 'config.json'
}
if (-not (Test-Path -LiteralPath $ConfigPath)) {
    Write-Error "Config not found: $ConfigPath"
    return
}
$Config = Get-Content -LiteralPath $ConfigPath -Raw | ConvertFrom-Json
# files named in the config (notify.passwordFile) are relative to the config's dir
$ConfigDir = Split-Path -Parent (Resolve-Path -LiteralPath $ConfigPath).Path

$VarDir = Get-VarDir
$SpoolRoot = Get-SpoolDefault
if ((Test-HasProp $Config 'spool') -and $Config.spool) {
    $SpoolRoot = $Config.spool
}
$Paths = @{
    BaseDir    = $BaseDir
    EventsPath = Join-Path $VarDir 'events.jsonl'
    LockPath   = Join-Path $VarDir 'sequencer.lock'
    SpoolRoot  = $SpoolRoot
}

# only 'show' and 'trash' take positional arguments; anywhere else they're a typo
# (e.g. a misspelled switch), so refuse rather than silently ignore them
if ($RunRef -and $Command -notin @('show', 'trash')) {
    Write-Host "Unexpected argument(s) for '$Command': $($RunRef -join ' ')"
    exit 2
}

switch ($Command) {
    'plan' {
        $projection = Get-ServiceProjection -EventsPath $Paths.EventsPath
        $planNow = Get-Date
        $plan = Get-BackupPlan -Config $Config -Projection $projection -At $planNow
        $coverageMargin = if (Test-HasProp $Config 'coverageMargin') { [double]$Config.coverageMargin } else { 0.02 }
        Write-Host ("Plan  window={0}-{1}  (within window now: {2})  [* = mandatory, by score; last = last archive, or last backup without archiver]" -f `
                $Config.window.open, $Config.window.close, (Test-WithinWindow $Config.window.open $Config.window.close))
        foreach ($plannedJob in $plan) {
            $flag = if ($plannedJob.Mandatory) { '*' } else { ' ' }
            $lastCovered = Format-DisplayTime $plannedJob.LastCovered
            $overdue = if ($plannedJob.Overdue -ge 1e6) { 'new' } else { ('x{0:N1}' -f $plannedJob.Overdue) }
            # same test as the run's coverage gate
            $covered = if ($plannedJob.Overdue -lt (Get-CoverageThreshold -Margin $coverageMargin -PeriodSeconds $plannedJob.PeriodSeconds)) { ' covered' } else { '' }
            # never backed up with nothing measured: unknown, not "0s"
            $est = if (-not $plannedJob.LastSuccess -and $plannedJob.EstimatedSeconds -le 0) { '?' } else { Format-DurationUnit $plannedJob.EstimatedSeconds }
            Write-Host ("  {0} {1,-22} est={2,5}  overdue={3,-5}  score={4,7:N2}  last={5}{6}" -f `
                    $flag, $plannedJob.Service, $est, $overdue, $plannedJob.Score, $lastCovered, $covered)
        }
    }
    'run' {
        # the engine narrates the run live; here we only send the email report
        $InformationPreference = 'Continue'   # the run's narration lines
        $runId = Invoke-BackupRun -Config $Config -Paths $Paths -ForceWindow:$ForceWindow -ForceAllJobs:$ForceAllJobs
        if ($runId) { Send-RunReport -Config $Config -Paths $Paths -RunId $runId -BaseDir $ConfigDir }
    }
    'validate' {
        # dry preflight: check every enabled service's config + prerequisites, run nothing.
        $anyProblem = $false
        foreach ($name in $Config.services.PSObject.Properties.Name) {
            if (-not ((Test-HasProp $Config.services.$name 'enabled') -and [bool]$Config.services.$name.enabled)) { continue }
            $problems = @(Get-ServiceValidationProblems -Config $Config -Service $name -BaseDir $Paths.BaseDir -EventsPath $Paths.EventsPath)
            if ($problems.Count) {
                $anyProblem = $true
                Write-Host ("  {0,-22} INVALID" -f $name)
                foreach ($p in $problems) { Write-Host "      - $p" }
            }
            else {
                Write-Host ("  {0,-22} OK" -f $name)
            }
        }
        if ($anyProblem) {
            Write-Host ''
            Write-Host 'Validation found problems; fix the config before the next run.'
            exit 1
        }
    }
    'status' {
        $events = @(Get-BackupEvents -EventsPath $Paths.EventsPath)
        $runs = @(Get-RunStates -Events $events -LockPath $Paths.LockPath)
        if ($runs.Count -eq 0) { Write-Host 'idle  no runs recorded yet'; return }
        $current = $runs[-1]
        $prefix = if ($current.State -eq 'finished') { 'idle  last ' } else { '' }
        Format-RunDetail -Detail (Get-RunDetail -Events $events -Run $current) -Prefix $prefix | ForEach-Object { Write-Host $_ }
        # an older dead run is worth a mention even when the newest one is fine
        foreach ($r in @($runs | Select-Object -SkipLast 1 | Where-Object { $_.State -eq 'interrupted' } | Select-Object -Last 3)) {
            Write-Host ("note: run {0} ({1}) was interrupted - bseq show {0}" -f $r.RunId, (Format-EventTime $r.Start))
        }
    }
    'show' {
        $events = @(Get-BackupEvents -EventsPath $Paths.EventsPath)
        $runs = @(Get-RunStates -Events $events -LockPath $Paths.LockPath)
        $refs = @(if ($RunRef) { $RunRef } else { 'latest' })   # @() outside: an if-expression unrolls a 1-item array
        $failed = $false
        for ($i = 0; $i -lt $refs.Count; $i++) {
            if ($i -gt 0) { Write-Host '' }
            try { $run = Resolve-RunRef -Runs $runs -Ref $refs[$i] }
            catch { Write-Host $_.Exception.Message; $failed = $true; continue }
            Format-RunDetail -Detail (Get-RunDetail -Events $events -Run $run) | ForEach-Object { Write-Host $_ }
        }
        if ($failed) { exit 1 }
    }
    'history' {
        $events = @(Get-BackupEvents -EventsPath $Paths.EventsPath)
        $runs = @(Get-RunStates -Events $events -LockPath $Paths.LockPath | Select-Object -Last $Limit)
        [array]::Reverse($runs)
        foreach ($r in $runs) {
            Write-Host (Format-RunHistoryLine -Detail (Get-RunDetail -Events $events -Run $r))
        }
    }
    'trash' {
        $trashRoot = (Get-SpoolPaths -SpoolRoot $Paths.SpoolRoot).Trash
        $events = @(Get-BackupEvents -EventsPath $Paths.EventsPath)
        $items = @(Get-TrashItems -TrashRoot $trashRoot -Events $events)
        $names = @($RunRef | Where-Object { $_ })
        $present = @($items | ForEach-Object { $_.Name })
        $unknown = @($names | Where-Object { $_ -notin $present })
        foreach ($u in $unknown) { Write-Host "not in trash: $u" }
        if ($names.Count) { $items = @($items | Where-Object { $_.Name -in $names }) }

        if ($Delete) {
            if ($items.Count -eq 0) { Write-Host 'nothing to delete'; if ($unknown.Count) { exit 1 }; return }
            $lockInfo = @{}
            if (-not (Enter-SequencerLock -LockPath $Paths.LockPath -Info $lockInfo)) {
                Write-Host ("a run is in progress (pid {0}); nothing deleted" -f (Get-LockHolder -LockPath $Paths.LockPath))
                exit 1
            }
            try {
                Reset-RunOutput
                $InformationPreference = 'Continue'   # the [delete] lines, as in a run
                $sum = Clear-Trash -TrashRoot $trashRoot -EventsPath $Paths.EventsPath -Names @($items | ForEach-Object { $_.Name }) -By 'command'
                Write-Host ("freed {0} ({1} item{2}){3}" -f (Format-Size $sum.Bytes), $sum.Items, $(if ($sum.Items -ne 1) { 's' } else { '' }),
                    $(if ($sum.Kept) { ", $($sum.Kept) kept" } else { '' }))
            }
            finally { Exit-SequencerLock -LockPath $Paths.LockPath }
            if ($sum.Kept -or $unknown.Count) { exit 1 }
            return
        }

        $total = [double]0; foreach ($i in $items) { $total += $i.Bytes }
        Write-Host ("trash  {0}   {1} item{2}, {3}" -f $trashRoot, $items.Count, $(if ($items.Count -ne 1) { 's' } else { '' }), (Format-Size $total))
        foreach ($i in $items) {
            $origin = if ($i.Reason) {
                "{0,-12} {1,-20} run {2}  moved {3}" -f $i.Service, $i.Reason, $i.FromRun.Substring([math]::Max(0, $i.FromRun.Length - 4)), (Format-EventTime $i.MovedAt)
            }
            else { 'no record' }
            Write-Host ("  {0,-28} {1,9} {2,7} files  {3}" -f $i.Name, (Format-Size $i.Bytes), $i.Files, $origin)
        }
        # the last deletions, by runs or by hand
        $dels = @($events | Where-Object { $_.type -eq 'trash.delete' } | Select-Object -Last 5)
        if ($dels.Count) {
            Write-Host 'last deletions:'
            [array]::Reverse($dels)
            foreach ($d in $dels) {
                $byWhom = if ((Test-HasProp $d 'by') -and $d.by) { "by $($d.by)" } elseif (Test-HasProp $d 'runId') { 'run ' + ([string]$d.runId).Substring([math]::Max(0, ([string]$d.runId).Length - 4)) } else { '?' }
                $st = if ($d.status -eq 'ok') { (Format-Size ([double]$d.bytes)) } else { 'FAIL' }
                Write-Host ("  {0}  {1,-11} {2,9}  {3}" -f (Format-EventTime $d.ts), $byWhom, $st, $d.trashName)
            }
        }
        if ($unknown.Count) { exit 1 }
    }
    'test-notify' {
        if (-not (Test-HasProp $Config 'notify') -or -not $Config.notify) { Write-Host 'no notify section in the config'; exit 1 }
        if (-not ((Test-HasProp $Config.notify 'enabled') -and $Config.notify.enabled)) {
            Write-Host 'warning: notify.enabled is false: runs send no mail (sending this test anyway)'
        }
        $events = @(Get-BackupEvents -EventsPath $Paths.EventsPath)
        $runs = @(Get-RunStates -Events $events -LockPath $Paths.LockPath)
        $hostName = [System.Net.Dns]::GetHostName()
        $intro = "This is a test, sent by 'bseq test-notify' on $hostName at $(Format-EventTime ([datetime]::UtcNow))."
        if ($runs.Count) {
            $last = $runs[-1].RunId
            $subject = "[test] backup report $last"
            $body = $intro + " Below: the report of the last run.`n`n" + (Format-RunReport -EventsPath $Paths.EventsPath -RunId $last)
        }
        else {
            $subject = '[test] backup report'
            $body = $intro + ' No run recorded yet.'
        }
        $r = Send-BackupReport -Notify $Config.notify -Subject $subject -Body $body -BaseDir $ConfigDir -Force
        if ($r.Sent) { Write-Host ("sent '{0}' to {1}" -f $subject, (@($Config.notify.to) -join ', ')) }
        else { Write-Host "FAIL: $($r.Error)"; exit 1 }
    }
    default {
        Write-Host "Unknown command: $Command"
        Show-Usage
    }
}
